mapper.select:
SELECT * FROM knowledge_chapter WHERE user_id = #{userId}
ORDER BY priority DESC, name ASC
LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE knowledge_chapter
SET name = #{name}, category = #{category}, priority = #{priority}, mastery = #{mastery},
    question_count = #{questionCount}, correct_count = #{correctCount}, last_review_date = #{lastReviewDate}
WHERE id = #{id} AND user_id = #{userId}
